insert into public.dpe_categories (id, label, section_label, intro, sort_order, exam_type) values
  ('preflight-prep', 'Preflight Preparation', 'Section 2', 'This section covers the eligibility, currency, weather, and airworthiness foundation every IFR flight is planned against — the material a DPE expects an applicant to have completely settled before the first clearance is ever copied.', 0, 'instrument'),
  ('atc-clearances', 'Air Traffic Control Clearances and Procedures', 'Section 3', 'This section covers the language and structure of the ATC system itself — the specific words, priorities, and procedures that make an instrument pilot''s behavior predictable to controllers and safe within the IFR system.', 1, 'instrument'),
  ('instrument-flight', 'Instrument Flight', 'Section 4', 'This section covers the hands-on core of instrument flying — scan technique, unusual attitude recovery, partial panel operations, and the specific procedures for holding and course tracking that make up the bulk of the flight portion of the checkride.', 2, 'instrument'),
  ('navigation-systems', 'Navigation Systems', 'Section 5', 'This section covers the equipment behind instrument flying — VOR, GPS, and ILS systems, their known limitations, and how equipment capability directly determines which approach minima a pilot is legally authorized to use.', 3, 'instrument'),
  ('approach-procedures', 'Instrument Approach Procedures', 'Section 6', 'This section covers approach chart interpretation, minima, categories, and the judgment calls — missed approach, circling, stabilized approach criteria — that carry the most real-world safety weight in instrument flying.', 4, 'instrument'),
  ('emergency-ops-instrument', 'Emergency Operations', 'Section 7', 'This section covers instrument-specific failure modes — pitot-static, vacuum, and electrical system failures — and the judgment required to recognize and respond to them while flying solely by reference to instruments.', 5, 'instrument'),
  ('lost-comms', 'Lost Communications', 'Section 8', 'This section is dedicated entirely to 14 CFR 91.185 — the single most heavily tested procedural topic on most instrument checkrides, and one every applicant is expected to be able to apply precisely to a live, specific scenario.', 6, 'instrument'),
  ('postflight-procedures', 'Postflight Procedures', 'Section 9', 'This closing content section covers what happens after the flight — documentation, currency logging, and the habits that separate a pilot who merely stays legal from one who stays genuinely proficient.', 7, 'instrument');
insert into public.dpe_questions (id, category, question, model_answer, common_mistakes, dpe_evaluating, acs_reference, real_world_application, is_scenario, scenario_order, sort_order, exam_type) values
  ('ipf-1', 'preflight-prep', 'What are the aeronautical experience requirements to be eligible for an Instrument-Airplane rating under 14 CFR 61.65?', 'At least 50 hours of cross-country PIC flight time (in any category, with at least 10 hours in an airplane for an airplane instrument rating), and at least 40 hours of actual or simulated instrument time in the areas of operation, including at least 15 hours of instrument flight training from an authorized instructor, along with a cross-country flight under IFR of at least 250 nautical miles along airways or ATC-directed routing that includes an instrument approach at each of three different airports.', 'Confusing the 50-hour cross-country PIC requirement with the 40-hour instrument time requirement, or forgetting the specific three-airport, 250-nautical-mile cross-country detail.', 'Whether the applicant''s own logbook actually satisfies each distinct sub-requirement, not just a general sense that "I have enough hours."', 'Area of Operation I, Task A — Preflight Preparation (Pilot Qualifications).', 'This exact cross-country flight is often the single flight examiners ask an applicant to walk through in detail during the oral.', false, null, 0, 'instrument'),
  ('ipf-2', 'preflight-prep', 'What recency of experience is required to act as pilot in command under IFR, per 14 CFR 61.57(c)?', 'Within the preceding 6 calendar months, the pilot must have performed and logged at least 6 instrument approaches, holding procedures, and intercepting and tracking courses through the use of navigation systems — in actual weather conditions, under simulated instrument conditions using a view-limiting device, or in an approved flight simulator or training device representative of the aircraft category.', 'Recalling only the 6 approaches and forgetting that holding procedures and course intercept/tracking are separately required elements of currency.', 'Complete recall of all three currency elements, not just the most commonly cited one.', 'Area of Operation I, Task A — Preflight Preparation (Pilot Qualifications).', 'This is the actual rule a working instrument pilot checks before every IFR flight, not just before a checkride.', false, null, 1, 'instrument'),
  ('ipf-3', 'preflight-prep', 'If instrument currency lapses, what is the process to regain it?', 'There is a 6-calendar-month grace period after currency lapses during which the pilot may regain currency simply by performing the required approaches, holding, and course tracking again (with a safety pilot if flown under simulated conditions). If that additional 6 months also lapses — 12 months total since last current — an Instrument Proficiency Check (IPC) with an authorized instructor or examiner is required under 61.57(d).', 'Believing an IPC is required immediately upon any lapse, rather than only after the full 12-month window has elapsed.', 'Correct sequencing of the two windows: the 6-month grace period, then the IPC requirement.', 'Area of Operation I, Task A — Preflight Preparation (Pilot Qualifications).', 'Directly relevant to Andrew''s own CFII practice — IPCs are one of the more common instrument-related services flight instructors provide.', false, null, 2, 'instrument'),
  ('ipf-4', 'preflight-prep', 'What is the "1-2-3 rule" for determining whether an alternate airport must be filed?', 'An alternate is not required if, for at least one hour before through one hour after the estimated time of arrival, the forecast at the destination indicates a ceiling of at least 2,000 feet and visibility of at least 3 statute miles, and the airport has a published standard or special instrument approach procedure. If the forecast doesn''t meet this, an alternate must be filed.', 'Applying the 1-2-3 rule''s numbers to the alternate airport''s own required weather, rather than only using it to decide whether an alternate must be filed at all.', 'Whether the applicant separates "do I need an alternate" from "what weather does the alternate need," which are two different questions.', 'Area of Operation I, Task B — Preflight Preparation (Weather Information).', 'This determination happens on every real IFR flight plan filed, not just as an abstract regulation.', false, null, 3, 'instrument'),
  ('ipf-5', 'preflight-prep', 'Once an alternate airport is required, what weather minimums must it forecast to be legally listed?', 'For an airport with a published instrument approach, standard alternate minimums are a 600-foot ceiling and 2 statute miles visibility for a precision approach, or an 800-foot ceiling and 2 statute miles visibility for a non-precision approach, unless the approach procedure specifies different alternate minimums. If no instrument approach is published at the alternate, it must allow descent, approach, and landing under basic VFR.', 'Using the destination''s 1-2-3 rule numbers (2,000 and 3) for the alternate itself, when the alternate has its own, generally lower, standard minimums.', 'Whether the applicant knows the alternate''s minimums are a genuinely separate, generally more permissive standard from the destination''s filing threshold.', 'Area of Operation I, Task B — Preflight Preparation (Weather Information).', 'Examiners frequently combine this with the 1-2-3 rule as one flowing scenario question about a specific flight plan.', false, null, 4, 'instrument'),
  ('ipf-6', 'preflight-prep', 'What equipment is an aircraft required to have to be legally flown under IFR, beyond standard day/night VFR equipment?', 'Per 14 CFR 91.205(d), IFR flight requires — in addition to VFR equipment — two-way radio and navigation equipment suitable for the route, a gyroscopic rate-of-turn indicator, a slip/skid indicator, a sensitive altimeter adjustable for barometric pressure, a clock with a sweep-second hand or equivalent digital display, a generator or alternator, and gyroscopic pitch-and-bank and directional indicators.', 'Reciting only the day-VFR equipment list from memory and forgetting this is an additive list specific to IFR operations.', 'Precise, complete recall of the IFR-specific additions rather than a general sense that "you need more instruments."', 'Area of Operation I, Task E — Preflight Preparation (Airworthiness Requirements).', 'Relevant every time evaluating whether a specific aircraft is legally equipped for a planned IFR flight.', false, null, 5, 'instrument'),
  ('ipf-7', 'preflight-prep', 'What inspections specific to IFR operation are required beyond the standard annual inspection, and how often?', 'The pitot-static system and altimeter must be tested and inspected within the preceding 24 calendar months per 91.411, and the transponder — including any altitude reporting equipment — must be tested within the preceding 24 calendar months per 91.413.', 'Assuming the standard annual inspection alone covers these IFR-specific checks, when they are separate, specifically timed requirements.', 'Whether the applicant knows these are distinctly IFR-specific inspection requirements layered on top of the general maintenance schedule.', 'Area of Operation I, Task E — Preflight Preparation (Airworthiness Requirements).', 'A lapsed pitot-static or transponder check is an easy, easily-overlooked way to become illegal for IFR flight even in an otherwise airworthy aircraft.', false, null, 6, 'instrument'),
  ('ipf-8', 'preflight-prep', 'How does spatial disorientation develop, and what are two illusions an instrument pilot should specifically understand?', 'Spatial disorientation occurs when the vestibular system''s sense of motion or orientation conflicts with the aircraft''s actual attitude, especially without outside visual reference. The leans (a false sensation of banking after a slow roll-in the inner ear didn''t register as a coordinated turn) and the graveyard spiral (a continued sensation of a level turn after actually rolling out, tempting a pilot to re-enter a bank and inadvertently tighten a descending spiral) are two classic examples.', 'Believing physical sensation is a reliable backup to the instruments, rather than a genuinely unreliable source of information in IMC.', 'Whether the applicant''s answer reinforces "trust the instruments, not the inner ear" as the actual operative principle, not just definitions.', 'Area of Operation I, Task D — Preflight Preparation (Human Factors).', 'This is the physiological root of many real IMC loss-of-control accidents — genuinely important beyond the oral exam itself.', false, null, 7, 'instrument'),
  ('iatc-1', 'atc-clearances', 'What are the components of a standard IFR clearance, using the CRAFT mnemonic?', 'Clearance limit (the fix or airport the clearance is valid to), Route (the specific routing assigned), Altitude (initial and any expect-further-clearance altitude), Frequency (departure frequency), and Transponder code — the standard elements copied and read back to confirm a full IFR clearance.', 'Omitting the clearance limit specifically, since pilots often focus on route, altitude, frequency, and squawk and forget to note what the clearance is actually valid to.', 'Complete, ordered recall of all five elements as they''d actually be delivered and read back on a real clearance.', 'Area of Operation III, Task A — Air Traffic Control Clearances and Procedures.', 'Copied verbatim on every real IFR departure — genuinely operational knowledge, not just checkride trivia.', false, null, 0, 'instrument'),
  ('iatc-2', 'atc-clearances', 'What is a clearance void time, and what must a pilot do if unable to depart before it?', 'A clearance void time is a specific time by which the aircraft must be airborne, or the clearance is void. If unable to depart before that time, the pilot must contact ATC — typically by phone, since this scenario is common at non-towered fields — to cancel or obtain a new clearance before attempting takeoff.', 'Departing after the void time has passed, assuming the original clearance is still valid.', 'Whether the applicant understands departing after a void time without a new clearance is a real regulatory violation, not just poor practice.', 'Area of Operation III, Task A — Air Traffic Control Clearances and Procedures.', 'Common at non-towered airports for an IFR departure into low IMC.', false, null, 1, 'instrument'),
  ('iatc-3', 'atc-clearances', 'What is the difference between being cleared "as filed" and receiving a full route clearance?', '"Cleared as filed" means the routing in the clearance matches exactly what was filed, and the pilot copies only the non-route elements of CRAFT; a full route clearance is read in its entirety because it differs from what was filed, requiring the pilot to copy every fix and airway explicitly.', 'Assuming "cleared as filed" means nothing needs to be copied at all, rather than just the route portion.', 'Whether the applicant still expects to copy CRAFT''s non-route elements even on an "as filed" clearance.', 'Area of Operation III, Task A — Air Traffic Control Clearances and Procedures.', 'Misreading "as filed" as "nothing to write down" is a common, avoidable new-instrument-pilot mistake.', false, null, 2, 'instrument'),
  ('iatc-4', 'atc-clearances', 'What is the difference between "climb via" and a standard climb clearance on a Standard Instrument Departure (SID)?', '"Climb via" instructs the pilot to comply with the SID''s lateral path and all published altitude and/or speed restrictions along it without individual ATC clearance for each step, until reaching the assigned or top altitude; a standard climb clearance to a specific altitude, without "climb via," generally means the published crossing restrictions don''t apply unless separately stated.', 'Complying with published altitude restrictions on a SID when only a standard climb clearance — no "climb via" — was actually issued.', 'Whether the applicant distinguishes exactly which clearance phrasing activates the published vertical profile.', 'Area of Operation III, Task A / Area IV, Task A — Air Traffic Control Clearances, Instrument Flight.', 'A genuinely common point of confusion, and getting it wrong can mean busting an altitude restriction on a real departure.', false, null, 3, 'instrument'),
  ('iatc-5', 'atc-clearances', 'What are Minimum En Route Altitude (MEA), Minimum Obstruction Clearance Altitude (MOCA), and Minimum Crossing Altitude (MCA), and how do they differ?', 'MEA is the lowest published altitude ensuring acceptable navigation signal coverage and obstacle clearance along an entire airway segment; MOCA guarantees obstacle clearance — with navigation signal only assured within 22 nautical miles of a VOR — and may be lower than the MEA; MCA is a specific altitude a pilot must reach before crossing a fix, typically where the MEA increases sharply ahead.', 'Using MOCA as a general cruising altitude beyond 22 nautical miles from the associated VOR, where reliable navigation signal is no longer guaranteed.', 'Precise distinction between all three, not just recall of MEA alone.', 'Area of Operation III, Task A — Air Traffic Control Clearances and Procedures.', 'Reading these directly off an en route chart is a common, concrete oral-exam exercise.', false, null, 4, 'instrument'),
  ('iatc-6', 'atc-clearances', 'What must a pilot do if issued an ATC clearance they''re unable to comply with?', 'Advise ATC immediately using the word "unable," along with the reason if practical, and request an amended clearance. A pilot should never simply deviate from a clearance without notifying ATC except under the pilot in command''s genuine emergency authority under 91.3(b).', 'Silently deviating from an assigned altitude or routing due to weather or terrain without first communicating with ATC, outside of a true declared emergency.', 'Whether the applicant defaults to communicating first, reserving unilateral deviation for true emergencies only.', 'Area of Operation III, Task A — Air Traffic Control Clearances and Procedures (Risk Management).', '"Unable" is one of the most operationally important words in a real pilot''s IFR vocabulary.', false, null, 5, 'instrument'),
  ('iatc-7', 'atc-clearances', 'What is a clearance limit, and what should a pilot do upon reaching it if no further clearance has been received?', 'A clearance limit is the fix, point, or airport to which an IFR clearance is issued. If the limit isn''t the destination and no further clearance has been received, and it''s not a fix from which an approach begins, the pilot should hold at that fix and request further clearance — specific lost-communications procedures apply if radio contact has also been lost.', 'Continuing past the clearance limit without further clearance, assuming the original route implicitly continues.', 'Whether the applicant knows holding — not continuing — is the default action absent further clearance.', 'Area of Operation III, Task A — Air Traffic Control Clearances and Procedures.', 'This scenario overlaps directly with the lost communications procedures covered later in this guide.', false, null, 6, 'instrument'),
  ('iatc-8', 'atc-clearances', 'What is expected of a pilot when ATC issues a safety alert?', 'A safety alert obligates ATC to warn a pilot if aware the aircraft is in a position considered unsafe due to terrain, obstruction, or another aircraft. The pilot should acknowledge the alert and take immediate action as necessary for safety, using their own judgment even if it means deviating from the current clearance, then advising ATC as soon as practical.', 'Waiting for a formal clearance amendment before responding to a safety alert, when immediate pilot judgment and action is actually expected.', 'Whether the applicant treats a safety alert as an immediate action item, not just an informational advisory.', 'Area of Operation III, Task A — Air Traffic Control Clearances and Procedures (Risk Management).', 'Safety alerts are a real, if uncommon, part of the ATC system''s designed safety net — know your role in it.', false, null, 7, 'instrument'),
  ('iflt-1', 'instrument-flight', 'What is the difference between a primary and a supporting instrument in the instrument scan, and why does it matter?', 'The primary instrument for a given control — pitch, bank, or power — is the one that most directly and specifically indicates that parameter at a stable state, while supporting instruments corroborate that reading. Effective scanning relies on identifying which instrument is primary for the current phase of flight, rather than fixating on the attitude indicator alone.', 'Fixating on the attitude indicator throughout every phase of flight rather than shifting the primary/supporting relationship as airspeed, configuration, and desired flight path change.', 'Whether the applicant understands the primary instrument changes with the specific maneuver being flown, not fixed to one instrument always.', 'Area of Operation IV, Task A — Instrument Flight (Basic Instrument Flight Maneuvers).', 'This scanning discipline is the actual skill evaluated throughout the entire flight portion of the checkride, not just discussed on the ground.', false, null, 0, 'instrument'),
  ('iflt-2', 'instrument-flight', 'What is the correct procedure for recovering from an unusual attitude using instruments alone?', 'First, cross-check the attitude indicator, airspeed, and altimeter/VSI to determine a nose-high or nose-low condition. For a nose-low attitude: reduce power, level the wings, then raise the nose to level flight. For a nose-high attitude: add power, level the wings, then lower the nose to prevent an approaching stall.', 'Correcting bank and pitch in the wrong order, or failing to add or reduce power appropriately for the specific nose-high or nose-low condition.', 'Correct sequencing of control inputs specific to the type of unusual attitude, not a single generic recovery response.', 'Area of Operation IV, Task B — Instrument Flight (Recovery from Unusual Flight Attitudes).', 'This exact maneuver, hood-on, is a standard, expected task during the flight portion of the checkride.', false, null, 1, 'instrument'),
  ('iflt-3', 'instrument-flight', 'What instruments are lost in a vacuum system failure, and how does a pilot compensate?', 'A vacuum failure typically disables the attitude indicator and heading indicator in vacuum-driven systems, since both rely on vacuum-powered gyros. The pilot compensates by relying on the electrically powered turn coordinator for bank information, the magnetic compass for heading, and the altimeter, airspeed, and VSI for pitch information — a genuine partial-panel scan.', 'Continuing to reference the failed attitude indicator out of habit rather than actively recognizing the failure and switching to the partial-panel scan.', 'Whether the applicant can promptly recognize the failure pattern and shift to the correct supporting instruments.', 'Area of Operation VII, Task A — Emergency Operations (Loss of Primary Flight Instruments).', 'Partial panel work under the hood is a standard, expected checkride task, not just an oral discussion topic.', false, null, 2, 'instrument'),
  ('iflt-4', 'instrument-flight', 'How do you determine which type of holding pattern entry — direct, teardrop, or parallel — to use?', 'Compare the inbound heading to the holding course, generally dividing the entry sectors into thirds around the holding fix relative to the inbound holding course: a direct entry is used approaching roughly from within the holding side, a teardrop entry from the outside on the non-holding side at a shallow angle, and a parallel entry from the outside on the non-holding side at a wider angle. Most modern GPS navigators compute and display the correct entry automatically.', 'Overcomplicating the mental sector math in the moment rather than trusting the navigator''s computed entry when available, while still understanding the underlying logic for partial-panel or non-GPS scenarios.', 'Whether the applicant understands the underlying logic well enough to fly a correct entry even without automation.', 'Area of Operation IV, Task D — Instrument Flight (Holding Procedures).', 'Holding entries remain a standard checkride task even in a fully GPS-equipped, glass-panel aircraft.', false, null, 3, 'instrument'),
  ('iflt-5', 'instrument-flight', 'What are the standard timing and wind correction procedures within a holding pattern?', 'Standard holding pattern legs are timed at one minute at or below 14,000 feet MSL (1.5 minutes above), with inbound leg timing adjusted based on outbound leg results, and wind correction applied by adjusting the outbound heading roughly three times the correction used inbound, to compensate for the wind''s fuller effect over the longer outbound distance.', 'Applying the same wind correction angle on both inbound and outbound legs, rather than the larger correction needed outbound.', 'Whether the applicant understands why the outbound correction must be proportionally larger, not just that a correction exists.', 'Area of Operation IV, Task D — Instrument Flight (Holding Procedures).', 'Precise holding pattern flying directly affects fuel planning on a real IFR flight with holding delays.', false, null, 4, 'instrument'),
  ('iflt-6', 'instrument-flight', 'What is a DME arc procedure, and what is the basic technique for flying one?', 'A DME arc is a curved course flown at a constant distance from a DME-equipped navaid, typically used to transition onto an instrument approach. The basic technique is the "10-degree bracket" method — turning 10 degrees toward the arc when the DME reading increases beyond the target distance, and 10 degrees away when it decreases below it, making small corrections to track the constant-radius arc.', 'Overcorrecting with large heading changes rather than the small, incremental bracket corrections the technique is built around.', 'Whether the applicant can describe the practical flying technique, not just the definition of a DME arc.', 'Area of Operation IV, Task D / Area V, Task A — Instrument Flight, Navigation Systems.', 'Still found on some real-world approach transitions, particularly in mountainous or complex terminal airspace.', false, null, 5, 'instrument'),
  ('iflt-7', 'instrument-flight', 'What is the general technique for intercepting a navigational course, whether VOR or GPS?', 'Determine the current position relative to the desired course, select an intercept heading — commonly 30 to 45 degrees relative to the course — and turn to that heading. As the CDI needle approaches center, begin turning toward the course heading, leading the turn based on closure rate so the aircraft rolls out established on course rather than overshooting through it.', 'Waiting until the CDI needle is fully centered before beginning the turn onto course, resulting in an overshoot through the desired course.', 'Whether the applicant understands the concept of leading the turn based on rate of closure, not just reacting to the needle at the last moment.', 'Area of Operation IV, Task E — Instrument Flight (Intercepting and Tracking Navigational Systems).', 'This technique is used continuously throughout an actual IFR flight, on nearly every course change.', false, null, 6, 'instrument'),
  ('iflt-8', 'instrument-flight', 'Once established on course, how should a pilot correct for wind drift while tracking a navigational course?', 'Apply a wind correction angle proportional to the amount of needle deflection and known wind conditions, then fine-tune in smaller increments as the aircraft re-centers, aiming to settle into and hold the specific heading — the crab angle — that keeps the needle centered over time rather than repeatedly chasing the needle with large corrections.', 'Repeatedly overcorrecting in large increments every time the needle drifts slightly, rather than settling into a stable crab angle.', 'Whether the applicant demonstrates an understanding of proportional, decreasing corrections rather than a constant large-correction chase.', 'Area of Operation IV, Task E — Instrument Flight (Intercepting and Tracking Navigational Systems).', 'Smooth course tracking is one of the most continuously evaluated skills throughout the entire flight portion of the checkride.', false, null, 7, 'instrument'),
  ('inav-1', 'navigation-systems', 'What are two common VOR receiver behaviors an instrument pilot should recognize, and what causes them?', 'Station passage causes rapid needle swings and TO/FROM flag fluctuation as the aircraft flies through the "cone of confusion" directly above the station; general VOR accuracy also degrades with distance and can be affected by terrain or line-of-sight limitations at low altitude, since VOR is a line-of-sight navigation system.', 'Interpreting erratic needle behavior directly over a VOR station as a system malfunction rather than expected cone-of-confusion behavior.', 'Whether the applicant recognizes station passage behavior as normal and expected, not a fault condition.', 'Area of Operation V, Task A — Navigation Systems.', 'Recognizing station passage correctly is directly relevant to timing en route position reports and approach procedures built around VOR fixes.', false, null, 0, 'instrument'),
  ('inav-2', 'navigation-systems', 'What is RAIM, and why does it matter for GPS-based IFR navigation?', 'Receiver Autonomous Integrity Monitoring (RAIM) is the GPS receiver''s internal check that enough satellites are available and geometrically positioned to confirm the position solution is reliable, and to detect a faulty signal. A RAIM warning means the GPS position can no longer be relied upon for the current phase of flight, particularly critical during an approach.', 'Continuing to rely on GPS-displayed position after a RAIM warning appears, rather than treating it as an immediate navigation reliability concern.', 'Whether the applicant understands RAIM as an active reliability check, not a passive background feature.', 'Area of Operation V, Task A — Navigation Systems.', 'A RAIM warning during an actual approach requires an immediate transition to another means of navigation or a missed approach.', false, null, 1, 'instrument'),
  ('inav-3', 'navigation-systems', 'What is the practical difference between a WAAS-enabled and a non-WAAS GPS for instrument approaches?', 'WAAS (Wide Area Augmentation System) provides increased position accuracy and integrity, enabling vertically guided minima such as LPV and LNAV/VNAV; a non-WAAS GPS is generally limited to LNAV-only minima, typically higher than WAAS-enabled minima at the same airport.', 'Assuming any GPS can fly any published RNAV line of minima, without checking whether the specific installed equipment supports WAAS-based vertical guidance.', 'Whether the applicant connects equipment capability directly to which specific approach minima line is legally usable.', 'Area of Operation V, Task A — Navigation Systems.', 'Directly relevant to Apex''s own glass-cockpit specialty and equipment-specific instruction.', false, null, 2, 'instrument'),
  ('inav-4', 'navigation-systems', 'What are the ground components of an ILS, and what does each provide?', 'The localizer provides lateral (course) guidance aligned with the runway centerline; the glideslope provides vertical guidance to the runway touchdown zone; marker beacons — or DME/GPS substitution — identify specific distances along the approach; approach lighting systems provide visual guidance once visual contact is established near minimums.', 'Confusing localizer and glideslope roles, or forgetting that marker beacons are commonly substituted today by DME or GPS-based distance information.', 'Whether the applicant can name each component''s specific function, not just "the ILS gives you guidance."', 'Area of Operation V, Task A — Navigation Systems.', 'Understanding each component individually helps diagnose a partial ILS equipment failure — such as a glideslope-out condition — during an actual approach.', false, null, 3, 'instrument'),
  ('inav-5', 'navigation-systems', 'What do the different lines of minima on an RNAV (GPS) approach chart — LPV, LNAV/VNAV, LNAV, circling — represent?', 'LPV (Localizer Performance with Vertical guidance) offers the lowest minima with WAAS-based precision-like vertical guidance; LNAV/VNAV provides vertical guidance via WAAS or a certified barometric VNAV system, generally with slightly higher minima than LPV; LNAV provides lateral guidance only, flown to an MDA rather than a DA, generally with the highest minima of the vertically guided lines; circling minima apply when maneuvering visually to land on a runway not served directly by the approach''s final course.', 'Attempting to fly LPV-line minima with equipment that only supports LNAV, resulting in an illegal or unsafe approach below the equipment''s actual capability.', 'Whether the applicant matches available minima lines directly to the aircraft''s actual installed equipment capability.', 'Area of Operation V, Task A / Area VI, Task A — Navigation Systems, Instrument Approach Procedures.', 'Reading and correctly selecting the applicable minima line is a core, practical checkride approach-briefing task.', false, null, 4, 'instrument'),
  ('inav-6', 'navigation-systems', 'What VOR accuracy check methods and tolerances apply for IFR use, per 91.171?', 'Acceptable methods include a VOT test facility (±4° tolerance), a certified ground checkpoint (±4°), a certified airborne checkpoint (±6°), or a dual VOR cross-check between two receivers (must agree within 4° of each other) — performed within the preceding 30 days and logged with date, location, error, and signature.', 'Forgetting the logging requirement, or confusing which tolerance applies to which specific check method.', 'Precise recall of both the tolerances and the required logbook documentation.', 'Area of Operation I, Task E / Area V, Task A — Airworthiness Requirements, Navigation Systems.', 'A favorite live-recitation question because it combines a regulation with an actual logbook entry.', false, null, 5, 'instrument'),
  ('inav-7', 'navigation-systems', 'What should a pilot do if GPS signal is lost or a RAIM warning occurs during an approach in IMC?', 'Immediately transition to an alternate means of navigation appropriate to the situation — such as reverting to a ground-based navaid approach if available, or executing the missed approach procedure if no reliable alternate navigation source is available — and notify ATC of the equipment issue.', 'Continuing the approach on a degraded or lost GPS signal, hoping the position solution self-corrects before reaching minimums.', 'Whether the applicant defaults to an immediate, conservative response rather than continuing to press toward minimums on unreliable navigation.', 'Area of Operation V, Task A — Navigation Systems (Risk Management).', 'A genuinely real scenario given the reliance on GPS navigation in modern IFR flying.', false, null, 6, 'instrument'),
  ('inav-8', 'navigation-systems', 'What does the distinction between TSO-C129 and TSO-C146 GPS equipment mean for approach authorization?', 'TSO-C129 equipment is an earlier-generation, non-WAAS GPS standard generally limited to GPS overlay and LNAV-only approaches; TSO-C146 equipment is the WAAS-capable standard required to fly approaches with vertically guided LPV or LNAV/VNAV minima.', 'Assuming any GPS labeled "IFR certified" automatically supports the lowest available minima line on a given approach chart.', 'Whether the applicant connects the specific TSO standard of their own aircraft''s installed equipment to which approach minima they''re legally authorized to fly.', 'Area of Operation V, Task A — Navigation Systems.', 'Directly relevant to Apex''s glass-cockpit specialty — know the actual installed equipment''s TSO standard for every aircraft flown.', false, null, 7, 'instrument'),
  ('iapp-1', 'approach-procedures', 'What are the main sections of an instrument approach chart, and what does each show?', 'The briefing/header strip lists the approach name, frequencies, and minimum safe altitudes; the plan view shows the approach course and surrounding terrain and obstacles from above; the profile view shows the vertical descent path, step-down fixes, and the final approach fix; the minimums section lists the applicable DA/MDA and visibility requirements by approach category.', 'Skipping the plan view during a real approach briefing and focusing only on frequencies and minimums, missing terrain or course-reversal information depicted there.', 'Whether the applicant can navigate an unfamiliar approach chart methodically, section by section, rather than searching randomly for specific numbers.', 'Area of Operation VI, Task A — Instrument Approach Procedures.', 'Examiners commonly hand the applicant an unfamiliar approach chart and ask them to brief it live during the oral exam.', false, null, 0, 'instrument'),
  ('iapp-2', 'approach-procedures', 'What is the difference between Decision Altitude (DA) and Minimum Descent Altitude (MDA)?', 'DA applies to approaches with vertical guidance, such as an ILS or LPV, and is the altitude at which a missed approach must be initiated if required visual references aren''t in sight, allowing a smooth, continuous descent profile; MDA applies to non-precision, lateral-guidance-only approaches and is a hard altitude floor that may not be descended below until the runway environment is in sight, typically flown level for a period before either landing or executing the missed approach.', 'Descending below MDA "a little" while still looking for the runway, the way a brief momentary dip below DA might be treated on a precision approach.', 'Whether the applicant understands MDA as an absolute floor, in contrast to DA''s decision-point nature.', 'Area of Operation VI, Task A — Instrument Approach Procedures.', 'This distinction directly affects legal and safe approach technique on every non-precision approach flown.', false, null, 1, 'instrument'),
  ('iapp-3', 'approach-procedures', 'What determines an aircraft''s approach category, and why does it matter?', 'Approach category is based on 1.3 times the aircraft''s stall speed in the landing configuration at maximum certificated landing weight (or actual approach speed if greater), grouped into Category A (under 91 knots), B (91–120 knots), C (121–140 knots), and D (141–165 knots). It matters because each category has its own minima and, for circling approaches, its own protected maneuvering radius.', 'Assuming approach category is based on the aircraft''s cruise speed rather than its specific approach/landing speed.', 'Whether the applicant correctly identifies their own aircraft''s approach category and connects it to the correct minima line on a chart.', 'Area of Operation VI, Task A — Instrument Approach Procedures.', 'Using the wrong category''s minima or circling radius is a real, checkride-relevant error with genuine safety consequences.', false, null, 2, 'instrument'),
  ('iapp-4', 'approach-procedures', 'Under what conditions must a pilot execute the missed approach procedure?', 'A missed approach must be executed if, upon reaching DA, MDA, or the missed approach point, the required visual references for the runway aren''t in sight, or if the aircraft cannot maintain a normal rate of descent to landing, or if landing is not otherwise possible or advisable — and the decision must generally be made promptly at that point, not delayed while continuing to search visually.', 'Continuing past the missed approach point "just a little longer," hoping visual contact will occur.', 'Whether the applicant treats reaching DA/MDA/MAP without the required visual reference as an immediate, non-negotiable trigger for the missed approach.', 'Area of Operation VI, Task B — Instrument Approach Procedures (Missed Approach).', 'This decision point is one of the most heavily weighted judgment calls evaluated during the actual flight portion of the checkride.', false, null, 3, 'instrument'),
  ('iapp-5', 'approach-procedures', 'What is a circling approach, and what defines its protected maneuvering area?', 'A circling approach is flown to align visually with a landing runway not served directly by the approach''s final course, after reaching visual conditions at the circling MDA. The protected maneuvering area is defined by the aircraft''s approach category, with faster categories requiring a larger radius from the airport to remain within protected, obstacle-cleared airspace.', 'Flying a circling maneuver based on a fixed pattern size regardless of aircraft category, rather than the category-specific protected radius.', 'Whether the applicant connects circling technique directly to their own aircraft''s specific approach category.', 'Area of Operation VI, Task C — Instrument Approach Procedures (Circling Approach).', 'Circling approaches carry a disproportionate share of real approach-related accidents — genuinely important beyond the oral exam.', false, null, 4, 'instrument'),
  ('iapp-6', 'approach-procedures', 'What defines a "stabilized approach," and why is it emphasized in instrument training?', 'A stabilized approach generally means the aircraft is on the correct flight path, in the proper landing configuration, at an appropriate and steady airspeed and descent rate, with power set appropriately, by a defined point before landing. It''s emphasized because an unstabilized approach in IMC, close to the ground with limited visual reference, offers very little margin to safely correct before a controlled-flight-into-terrain risk develops.', 'Treating "stabilized approach" as only a jet or airline concept, rather than a directly relevant discipline for a single-engine instrument approach.', 'Whether the applicant connects the concept to real risk reduction in their own training aircraft, not just as textbook vocabulary.', 'Area of Operation VI, Task A — Instrument Approach Procedures (Risk Management).', 'An unstabilized approach is one of the most common real-world triggers for a "should have gone missed" moment.', false, null, 5, 'instrument'),
  ('iapp-7', 'approach-procedures', 'What is a Visual Descent Point (VDP), and how is it used?', 'A VDP is a defined point on the final approach course of a non-precision approach from which a normal descent from MDA to the runway touchdown point may begin, once required visual references are in sight; descending from MDA before reaching the VDP risks an excessively steep, unstable descent to the runway.', 'Beginning descent from MDA as soon as any visual reference appears, without regard to whether the VDP has actually been reached.', 'Whether the applicant connects the VDP directly to maintaining a stabilized, normal descent profile on a non-precision approach.', 'Area of Operation VI, Task A — Instrument Approach Procedures.', 'Not every non-precision approach publishes a VDP — know how to identify or estimate one when it isn''t charted.', false, null, 6, 'instrument'),
  ('iapp-8', 'approach-procedures', 'What is the difference between a contact approach and a visual approach?', 'A visual approach may be assigned by ATC or requested by the pilot when the destination has reported weather at or above VFR minimums and the pilot can proceed with visual reference to the airport or preceding traffic; a contact approach may only be requested by the pilot — never assigned by ATC — requires remaining clear of clouds with at least 1 statute mile flight visibility, and is used to expedite arrival at an airport with a published instrument approach when full IFR minimums may not otherwise be met.', 'Believing ATC can assign a contact approach the way they can a visual approach, when a contact approach must always be pilot-initiated.', 'Whether the applicant correctly identifies who may initiate each type of approach and under what specific minimum conditions.', 'Area of Operation VI, Task D — Instrument Approach Procedures (Visual and Contact Approaches).', 'A contact approach is a lesser-known but genuinely useful tool in the right circumstances — know it''s available and how it differs from a visual approach.', false, null, 7, 'instrument'),
  ('iemg-1', 'emergency-ops-instrument', 'How does a pilot recognize a pitot tube blockage in flight, and what are the resulting instrument indications?', 'A blocked pitot tube, with the static port still open, typically causes the airspeed indicator to act like an altimeter — indicating increasing airspeed during a climb and decreasing airspeed during a descent, independent of the aircraft''s actual speed — since the trapped pitot pressure no longer reflects true dynamic pressure while static pressure continues changing normally.', 'Trusting the airspeed indicator''s erroneous reading and adjusting pitch to "fix" an airspeed that isn''t actually changing as indicated.', 'Whether the applicant recognizes the specific, predictable failure pattern rather than treating any airspeed anomaly the same way.', 'Area of Operation VII, Task A — Emergency Operations (Loss of Primary Flight Instruments).', 'Recognizing this specific pattern quickly prevents a dangerous chase of a false airspeed indication in IMC.', true, null, 0, 'instrument'),
  ('iemg-2', 'emergency-ops-instrument', 'What happens to the instruments if the static port becomes blocked, and how can a pilot compensate?', 'A blocked static port causes the altimeter to freeze at the altitude where the blockage occurred, the VSI to read zero regardless of actual climb or descent, and the airspeed indicator to become unreliable during altitude changes. Many aircraft have an alternate static source that can be selected to restore normal, though slightly different-reading, instrument function.', 'Not knowing where the alternate static source selector is located or how to use it in the specific aircraft being flown.', 'Whether the applicant has genuine, aircraft-specific knowledge of their alternate static source location and effect, not just the general concept.', 'Area of Operation VII, Task A — Emergency Operations (Loss of Primary Flight Instruments).', 'Know this specific procedure for your own aircraft before you ever need it in actual IMC.', true, null, 1, 'instrument'),
  ('iemg-3', 'emergency-ops-instrument', 'What are the indications of a vacuum system failure, and how should a pilot respond?', 'A vacuum failure is often indicated by a vacuum gauge reading outside normal range, along with a slowly toppling or "sick" attitude indicator and heading indicator, rather than an instant, obvious failure. The pilot should recognize the pattern early through active cross-checking, cover or disregard the failed instruments, and transition to a partial-panel scan using the electrically powered turn coordinator, magnetic compass, and remaining pitot-static instruments.', 'Not actively monitoring the vacuum gauge as part of the routine scan, and instead discovering the failure only once the attitude indicator has already drifted significantly and misleadingly.', 'Whether the applicant includes the vacuum gauge itself as part of a proactive scan, catching a failure early rather than reactively.', 'Area of Operation VII, Task A — Emergency Operations (Loss of Primary Flight Instruments).', 'An early, subtle vacuum failure is more dangerous than an obvious one — active monitoring habits genuinely matter.', true, null, 2, 'instrument'),
  ('iemg-4', 'emergency-ops-instrument', 'What is the recommended response to an electrical system failure while operating in IMC?', 'Reduce electrical load by turning off non-essential equipment to conserve battery power, prioritize essential communication and navigation equipment, use backup or standby instruments as available, and plan to land at the nearest suitable airport — using pilotage and dead reckoning with any remaining navigation capability if avionics are significantly degraded.', 'Continuing to operate all electrical equipment normally, draining remaining battery reserve faster than necessary before finding a place to land.', 'Whether the applicant prioritizes load-shedding and a genuine plan to land promptly, rather than treating this as a minor inconvenience to fly through to the original destination.', 'Area of Operation VII, Task A — Emergency Operations (Electrical System and Related Malfunctions).', 'A full electrical failure in actual IMC is one of the more serious real-world emergencies an instrument pilot can face.', true, null, 3, 'instrument'),
  ('iemg-5', 'emergency-ops-instrument', 'In a combined emergency involving both an equipment failure and a communication issue in IMC, what is the correct order of priorities?', 'Aviate first — maintain aircraft control using whatever instruments remain reliable; navigate second — establish and maintain a safe course toward better conditions or a suitable airport; communicate third — attempt to notify ATC once the aircraft is under control and on a safe course, using whatever means remain available.', 'Attempting to communicate the problem to ATC before first ensuring the aircraft is under stable control, especially under partial panel conditions.', 'Whether the applicant applies aviate-navigate-communicate consistently, even under the compounded stress of a real dual-failure scenario.', 'Area of Operation VII, Task A — Emergency Operations (Risk Management).', 'This prioritization is the foundational judgment principle behind essentially every instrument emergency scenario.', true, null, 4, 'instrument'),
  ('iemg-6', 'emergency-ops-instrument', 'What is the appropriate response to encountering unexpected structural icing during an IFR flight?', 'Immediately request a course or altitude change from ATC to exit the icing conditions — descending to warmer air, climbing above a thin layer if performance allows, or reversing course toward known ice-free conditions — and avoid continuing further into icing hoping conditions improve; declare an emergency if performance becomes significantly degraded.', 'Continuing forward into worsening icing conditions while waiting for a routine altitude change request to be approved, rather than declaring the urgency of the situation.', 'Whether the applicant''s plan includes escalating to a direct, urgent request — or a declared emergency — if a routine request doesn''t produce a prompt response.', 'Area of Operation VII, Task A — Emergency Operations (Risk Management).', 'For a non-deiced training aircraft, this decision needs to happen at the very first sign of ice accumulation.', true, null, 5, 'instrument'),
  ('iemg-7', 'emergency-ops-instrument', 'What is the general procedure for an emergency descent in IMC?', 'Reduce power, establish a controlled bank to clear the descent path or advise ATC of the deviation, extend appropriate drag devices per the aircraft''s checklist, and descend at an airspeed and configuration appropriate to the aircraft, while communicating the emergency descent to ATC as soon as practical to ensure separation from other traffic.', 'Executing a rapid, uncoordinated descent without first notifying ATC, risking a genuine traffic conflict with other IFR aircraft nearby.', 'Whether the applicant balances the urgency of the descent against the real need to alert ATC for traffic separation.', 'Area of Operation VII, Task A — Emergency Operations (Risk Management, Skill).', 'Even in a genuine emergency, ATC coordination remains a critical safety layer that shouldn''t be skipped if at all possible.', true, null, 6, 'instrument'),
  ('iemg-8', 'emergency-ops-instrument', 'When should a pilot declare an emergency, and what authority does that grant under 14 CFR 91.3(b)?', 'A pilot should declare an emergency whenever facing a situation that compromises the safety of the flight and may require deviation from normal procedures, ATC instructions, or regulations to resolve safely — the threshold is the pilot''s own judgment, not a specific severity checklist. Under 91.3(b), the pilot in command has the authority to deviate from any rule to the extent required to meet that emergency.', 'Hesitating to declare an emergency out of concern about paperwork, embarrassment, or bothering ATC, when a genuine safety concern exists.', 'Whether the applicant treats "declare early" as the safer default, rather than waiting until a situation has become severe.', 'Area of Operation VII, Task A — Emergency Operations (Risk Management).', 'ATC would overwhelmingly rather a pilot declare early and have the situation resolve smoothly than delay and have it worsen.', true, null, 7, 'instrument'),
  ('ilc-1', 'lost-comms', 'What regulation governs lost communications procedures under IFR, and what is its general framework?', '14 CFR 91.185 governs two-way radio communications failure under IFR, establishing separate rules for the route and the altitude to fly when radio contact is lost while operating on an IFR flight plan in IMC, or conditions requiring IFR, so that ATC can predict the aircraft''s position and altitude and keep other traffic separated from it.', 'Treating lost communications as an undefined emergency requiring only general judgment, rather than recognizing 91.185 provides a specific, predictable framework ATC relies on.', 'Whether the applicant understands the entire purpose of 91.185 is to make the aircraft''s behavior predictable to ATC, not just to get the aircraft safely on the ground.', 'Area of Operation VII, Task B — Emergency Operations (Loss of Communications).', 'ATC actively uses this predictability to protect other IFR traffic around a lost-comm aircraft — this isn''t just a rule for the pilot''s own benefit.', false, null, 0, 'instrument'),
  ('ilc-2', 'lost-comms', 'What altitude should a pilot fly during a lost communications event, using the AVEF framework?', 'Fly the highest of: the Altitude last assigned by ATC, the minimum altitude (MEA) for IFR operation on the current route segment, the altitude ATC has told the pilot to Expect in a further clearance, or the altitude Filed in the flight plan — applying whichever is highest at each specific point along the route as conditions change.', 'Flying only the last assigned altitude for the entire remainder of the flight, rather than checking whether a higher MEA, expected altitude, or filed altitude applies at each subsequent route segment.', 'Whether the applicant understands AVEF must be reevaluated continuously along the route, not applied as a single static answer for the whole flight.', 'Area of Operation VII, Task B — Emergency Operations (Loss of Communications).', 'One of the single most commonly tested lost-comm oral exam questions — know it precisely and be ready to apply it to a specific scenario.', false, null, 1, 'instrument'),
  ('ilc-3', 'lost-comms', 'What route should a pilot fly during a lost communications event?', 'Fly, in order of priority: the route Assigned in the last ATC clearance; or if being radar Vectored, the direct route from the point of radio failure to the fix, route, or airway specified in the vector clearance; or the route ATC has told the pilot to Expect in a further clearance; or, absent any of these, the route Filed in the flight plan.', 'Defaulting immediately to the filed route without first checking whether a more specific assigned, vectored, or expected route actually applies to the situation.', 'Whether the applicant applies the correct route-priority order rather than jumping straight to the filed flight plan.', 'Area of Operation VII, Task B — Emergency Operations (Loss of Communications).', 'This route-priority logic pairs directly with the AVEF altitude framework — examiners often test both together in a single scenario.', false, null, 2, 'instrument'),
  ('ilc-4', 'lost-comms', 'If the clearance limit is a fix from which an approach begins, and no further clearance or expect-further-clearance time has been received, what should the pilot do?', 'If the expect-further-clearance time has passed, or none was received, the pilot should commence descent or descent and approach as close as possible to the estimated time of arrival calculated from the filed, or amended if known, flight plan.', 'Continuing to hold indefinitely at the clearance limit even after the calculated ETA has passed, rather than proceeding with the approach at that point.', 'Whether the applicant correctly identifies the specific trigger — ETA or EFC time, whichever governs — for beginning the approach.', 'Area of Operation VII, Task B — Emergency Operations (Loss of Communications).', 'This scenario is frequently paired with a specific practical timing calculation during the oral exam.', false, null, 3, 'instrument'),
  ('ilc-5', 'lost-comms', 'If the clearance limit is not a fix from which an approach begins, what should the pilot do?', 'Leave the clearance limit at the expect-further-clearance time if one was received, or if none was received, upon arrival over the clearance limit, and proceed to a fix from which an approach begins, arriving there as close as possible to the estimated time of arrival calculated from the filed or amended flight plan.', 'Continuing to hold indefinitely at a clearance limit that has no approach available from it, rather than proceeding onward per the regulation''s specific instructions.', 'Whether the applicant distinguishes this scenario from the prior question, since the correct action depends specifically on whether the clearance limit itself supports beginning an approach.', 'Area of Operation VII, Task B — Emergency Operations (Loss of Communications).', 'Examiners like probing both clearance-limit scenarios together to confirm the applicant hasn''t just memorized one version.', false, null, 4, 'instrument'),
  ('ilc-6', 'lost-comms', 'What should a pilot do if lost communications occur while operating in VFR conditions, even though on an IFR flight plan?', 'If VFR conditions are encountered at any point after a radio failure, the pilot should continue the flight under VFR and land as soon as practicable, rather than continuing to apply the IFR lost-communications altitude and route procedures.', 'Continuing to fly the IFR lost-comm procedure even after breaking out into clear VMC, when landing as soon as practicable under VFR is actually the correct response.', 'Whether the applicant recognizes that encountering VMC changes the entire lost-comm response, not just a minor detail within it.', 'Area of Operation VII, Task B — Emergency Operations (Loss of Communications).', 'A genuinely common real-world outcome, since many lost-comm events are equipment-related rather than tied to actual instrument weather.', false, null, 5, 'instrument'),
  ('ilc-7', 'lost-comms', 'What transponder code and actions should a pilot use during a lost communications event?', 'Squawk 7600 to alert ATC of the radio failure, and continue attempting to reestablish communication periodically on the current frequency, the last assigned frequency, and 121.5 MHz, while also monitoring for light gun signals if operating near a towered airport.', 'Forgetting to squawk 7600, relying only on ATC''s assumption that the aircraft has simply gone silent for another reason.', 'Whether the applicant knows the specific code and understands it as an active tool for alerting ATC, not just a passive requirement.', 'Area of Operation VII, Task B — Emergency Operations (Loss of Communications).', 'Squawking 7600 immediately is one of the fastest ways to help ATC recognize and respond appropriately to the situation.', false, null, 6, 'instrument'),
  ('ilc-8', 'lost-comms', 'What light gun signals should an instrument pilot recognize for use near a towered airport during lost communications?', 'A steady green means cleared to land (in flight) or cleared for takeoff (on the ground); a flashing green means return for landing (in flight) or cleared to taxi (on the ground); a steady red means give way to other traffic and continue circling (in flight) or stop (on the ground); a flashing red means airport unsafe, do not land (in flight) or taxi clear of the runway (on the ground).', 'Confusing steady versus flashing signals of the same color, since the difference between them changes the meaning significantly.', 'Complete, accurate recall of the full light gun signal set, not just the most commonly remembered "steady green."', 'Area of Operation VII, Task B — Emergency Operations (Loss of Communications).', 'A genuinely rare but real possibility if a lost-comm event occurs while arriving at a towered airport.', false, null, 7, 'instrument'),
  ('ipost-1', 'postflight-procedures', 'What must be logged after a flight for it to count toward instrument currency under 61.57(c)?', 'The date, the type of approach or procedure performed — identifying the specific approach if applicable — the location, and the name of the safety pilot if flown under simulated instrument conditions with a view-limiting device, along with confirmation that holding procedures and course intercepting/tracking were also performed within the required period.', 'Logging only "instrument approach practice" generically without recording the specific approach type, location, or safety pilot details needed to substantiate currency later.', 'Whether the applicant''s own logging habits would actually hold up as adequate documentation if currency were ever questioned.', 'Area of Operation VIII, Task A — Postflight Procedures.', 'Sloppy logging is a real, avoidable problem discovered only when a pilot needs to prove currency months later.', false, null, 0, 'instrument'),
  ('ipost-2', 'postflight-procedures', 'Can an approach flown in visual conditions, without an actual instrument reference need, still count toward currency?', 'Yes — an approach flown under simulated instrument conditions using an appropriate view-limiting device, with a qualified safety pilot, counts toward currency the same as one flown in actual IMC, as long as it is flown to at least MDA/DA (or the minimum altitude prescribed for the procedure) and to the missed approach point.', 'Believing only approaches flown in actual instrument meteorological conditions count toward legal currency.', 'Whether the applicant understands simulated instrument conditions are fully equivalent for currency purposes when properly conducted.', 'Area of Operation VIII, Task A — Postflight Procedures.', 'This is exactly how many instrument-rated pilots maintain currency during long stretches of good VFR weather.', false, null, 1, 'instrument'),
  ('ipost-3', 'postflight-procedures', 'What postflight documentation is required if an equipment discrepancy affecting IFR capability is discovered after landing?', 'The discrepancy should be documented in the aircraft''s maintenance discrepancy log or squawk sheet, and the aircraft should not be flown IFR again until the discrepancy is corrected and appropriately signed off, or is determined not to affect IFR airworthiness by a qualified mechanic.', 'Mentioning a discrepancy verbally to the next pilot or the maintenance shop without creating a written record in the aircraft''s logs.', 'Whether the applicant treats written documentation, not verbal notice, as the standard for maintenance discrepancy reporting.', 'Area of Operation VIII, Task A / Area I, Task E — Postflight Procedures, Airworthiness Requirements.', 'Written discrepancy logs are what actually protect the next pilot who flies the aircraft, especially at a flight school with multiple renters.', false, null, 2, 'instrument'),
  ('ipost-4', 'postflight-procedures', 'What is required to regain instrument privileges after currency has lapsed beyond the 6-month grace period?', 'An Instrument Proficiency Check (IPC), conducted by an authorized instructor or examiner per 61.57(d), covering the areas of operation appropriate to the instrument rating, with the specific content and scope at the discretion of the instructor or examiner conducting it based on the pilot''s actual experience gap.', 'Assuming a full instrument practical test retake is required, rather than the generally less extensive IPC.', 'Whether the applicant understands the IPC as a proficiency-restoring event tailored to the individual, not a fixed, standardized retest.', 'Area of Operation VIII, Task A — Postflight Procedures.', 'A common, genuinely valuable service that Apex and other flight schools provide to lapsed instrument pilots.', false, null, 3, 'instrument'),
  ('ipost-5', 'postflight-procedures', 'What is the purpose of the NASA Aviation Safety Reporting System (ASRS), and when might a pilot use it?', 'ASRS is a voluntary, confidential reporting system allowing pilots to report safety-related incidents — such as an altitude deviation or airspace incursion — without fear of certificate action in most cases, provided the report is filed within 10 days and the violation wasn''t deliberate or criminal; filing generally provides limited immunity from an FAA enforcement sanction for an inadvertent violation.', 'Assuming ASRS reporting guarantees complete immunity from any consequence, when it specifically protects against enforcement sanctions under defined conditions, not from other outcomes.', 'Whether the applicant understands both the value and the specific limits of ASRS protection.', 'Area of Operation VIII, Task A — Postflight Procedures.', 'Genuinely useful, real-world knowledge for any pilot who experiences an inadvertent deviation, including many IFR pilots over a full career.', false, null, 4, 'instrument'),
  ('ipost-6', 'postflight-procedures', 'What should a pilot do if contacted by ATC or the FAA after a flight regarding a possible pilot deviation?', 'Respond honestly and factually, request the specific details of the concern, and consider filing an ASRS report promptly if applicable and appropriate. A pilot facing potential enforcement action may also want to consult with an aviation attorney or a pilot organization''s legal services program before providing extensive statements.', 'Providing an extensive, informal explanation immediately without first understanding what specific deviation is being alleged.', 'Whether the applicant approaches this professionally and carefully, rather than reactively.', 'Area of Operation VIII, Task A — Postflight Procedures (Risk Management).', 'A genuinely useful, calm framework to have in mind before ever actually needing it.', false, null, 5, 'instrument'),
  ('ipost-7', 'postflight-procedures', 'What postflight debrief habits support ongoing instrument proficiency beyond simply logging the flight?', 'A genuine debrief includes reviewing which approaches, holds, or procedures felt shaky and specifically why, comparing planned versus actual fuel and time performance, and identifying any decision points during the flight that deserve further review or discussion with an instructor — turning each flight into a specific, targeted input for future training rather than just a logged number.', 'Treating the logbook entry itself as the complete record of the flight''s value, without any structured self-reflection on what actually went well or poorly.', 'Whether the applicant demonstrates a genuine continuous-improvement mindset, connecting to the broader ADM/SRM themes tested throughout the practical test.', 'Area of Operation VIII, Task A — Postflight Procedures (Risk Management).', 'This habit is exactly what separates pilots who maintain genuine proficiency from those who merely maintain legal currency.', false, null, 6, 'instrument'),
  ('ipost-8', 'postflight-procedures', 'What documentation should an applicant bring to a checkride to prove the required instrument aeronautical experience?', 'A complete, signed logbook showing all required hours — total cross-country PIC time, instrument time, dual instruction, the specific 250-nautical-mile three-airport cross-country flight, and recent instrument experience — the required instructor endorsements for the practical test and (if applicable) the knowledge test, and the Airman Knowledge Test Report.', 'Arriving with an incomplete logbook missing a specific required endorsement, or unable to point directly to the entries substantiating a specific regulatory requirement when asked.', 'Whether the applicant''s actual logbook, not just their general recollection, can substantiate every required element on request.', 'Area of Operation I, Task A — Preflight Preparation (Pilot Qualifications).', 'This is literally the first thing examined at the start of the checkride — get it right before anything else is evaluated.', false, null, 7, 'instrument');
insert into public.quick_reference_sheets (id, title, subtitle, rows, sort_order, exam_type) values
  ('qr-instrument-appendix', 'Instrument Quick Reference Appendix', 'Section 11 · Mnemonics, tolerances, and numbers for fast final-week review', '[["CRAFT", "CRAFT", "Clearance elements to copy: Clearance limit, Route, Altitude, Frequency, Transponder."], ["AVEF", "AVEF (Lost Comm Altitude)", "Fly the highest of: Assigned, Vectored (direct to the vector clearance''s fix/route), Expected, or Filed altitude."], ["Route", "Lost Comm Route Priority", "Assigned route, then Vectored (direct to the assigned fix/route), then Expected route, then Filed route."], ["1-2-3", "1-2-3 Rule", "No alternate required if, 1 hour before to 1 hour after ETA, forecast ceiling is at least 2,000 ft and visibility at least 3 SM."], ["Alt Mins", "Standard Alternate Minimums", "600-2 for a precision approach; 800-2 for a non-precision approach (unless the approach specifies otherwise)."], ["6-in-6", "6-in-6 Currency (61.57(c))", "6 instrument approaches, holding procedures, and course intercepting/tracking within the preceding 6 calendar months."], ["IPC", "IPC Trigger (61.57(d))", "Required once more than 6 months has elapsed since currency lapsed (12 months total since last current)."], ["DA/MDA", "DA vs. MDA", "DA: decision point on a vertically guided approach, continuous descent profile. MDA: hard floor on a non-precision approach, flown level until landing or missed."], ["Cat A-D", "Approach Categories", "A: under 91 kt. B: 91-120 kt. C: 121-140 kt. D: 141-165 kt — based on 1.3x stall speed at max landing weight."], ["Entries", "Holding Pattern Entries", "Direct, Teardrop, or Parallel, determined by the aircraft''s inbound heading relative to the holding course."], ["Timing", "Standard Holding Leg Timing", "1 minute at or below 14,000 ft MSL; 1.5 minutes above 14,000 ft MSL."], ["91.171", "VOR Check Tolerances", "VOT ±4°, ground checkpoint ±4°, airborne checkpoint ±6°, dual VOR cross-check within 4° of each other — every 30 days, logged."], ["91.411/.413", "IFR Equipment Inspections", "Pitot-static/altimeter (91.411) and transponder (91.413): every 24 calendar months."], ["7600", "Squawk 7600", "Lost communications."], ["7700", "Squawk 7700", "Emergency."], ["In Flight", "Light Gun Signals — In Flight", "Steady green: cleared to land. Flashing green: return for landing. Steady red: give way, continue circling. Flashing red: airport unsafe, do not land."], ["On Ground", "Light Gun Signals — On the Ground", "Steady green: cleared for takeoff. Flashing green: cleared to taxi. Steady red: stop. Flashing red: taxi clear of the runway."], ["IMSAFE", "IMSAFE", "Illness, Medication, Stress, Alcohol, Fatigue, Emotion/Eating — a personal preflight self-assessment."], ["PAVE", "PAVE", "Pilot, Aircraft, enVironment, External pressures — a risk-management framework for the whole flight, not just the pilot."], ["5 Ts", "5 Ts (Approach Checklist)", "Time, Turn, Twist, Throttle, Talk — a memory aid for actions at each approach fix."]]'::jsonb, 0, 'instrument');
insert into public.portal_lessons (id, title, meta, parts, sort_order, exam_type) values
  ('lesson-instrument-framework', 'Checkride Success Framework', 'Section 1 · How the instrument oral exam actually works', '[{"h": "Welcome Letter from Apex Aviation", "body": ["Welcome to the Apex Advantage Instrument Rating Checkride Prep Pack — and congratulations on reaching this stage of your training. Earning your private certificate taught you to fly the airplane. Earning your instrument rating teaches you to trust it completely, even when you can''t see a single reference outside the windscreen. That shift — from flying by what you see to flying by what you know and what the instruments tell you — is exactly what your DPE is evaluating.", "We built this guide the way we build every part of Apex Advantage: around a simple idea we call Train Beyond the Checkride. Your examiner isn''t testing whether you can recite regulations from memory. They''re testing whether you''re the kind of pilot who can be trusted, alone, in the clouds, to make sound decisions with no outside visual reference at all. Every question in this guide is built to develop that judgment, not just a script.", "This isn''t a textbook, and it isn''t a cram sheet. It''s a study partner — structured, scenario-based preparation you can work through at your own pace, the same way our live students train in Apex Advantage ground school. Use it well, and you won''t just pass your checkride. You''ll walk into it exactly the way you''ll want to feel on your first solid actual-IMC approach afterward: calm, because you already know you''re ready.", "Fly safe, study well, and welcome to Apex. — The Apex Aviation Team"]}, {"h": "How to Use This Guide", "list": ["Work section by section, in order — the sections follow the structure of a real instrument oral exam, moving from preflight planning and clearances through actual instrument flight, approaches, and the emergency and lost-communications scenarios examiners return to again and again.", "Don''t just read the Model Answer — cover it, answer the question out loud in your own words first, then compare. Speaking your answer, not just recognizing it, is what actually builds checkride-ready recall.", "Pay close attention to the Common Student Mistakes field for every question — these are the specific, predictable ways applicants lose confidence points, and knowing them in advance is half the battle.", "Use the ACS Connection field to cross-reference the current Instrument Rating Airman Certification Standards directly — this guide is a companion to the ACS, not a replacement for reading it.", "Keep the Quick Reference Appendix close during your final week of study — it''s built for fast review of the mnemonics and numbers examiners expect instantly, not first-time learning.", "If a question or concept still feels shaky after working through this guide, that''s useful information — bring it to your CFII directly rather than letting it go unresolved into checkride day."]}, {"h": "Understanding the FAA ACS", "body": ["The Instrument Rating Airman Certification Standards (ACS) is the actual rubric your DPE uses to evaluate you — not a general guideline, the specific, official standard. Every checkride question you''ll ever be asked traces back to a specific Area of Operation and Task within it.", "The ACS structure has three layers: Areas of Operation (the broad phases of instrument flight — Preflight Preparation, Air Traffic Control Clearances, Instrument Flight, Navigation Systems, Instrument Approach Procedures, Emergency Operations, and Postflight Procedures); Tasks (specific, named skills or knowledge sets within each Area); and within every Task, three elements — Knowledge, Risk Management, and Skill.", "Risk Management deserves particular attention in the instrument context. An instrument rating grants access to weather and conditions a VFR-only pilot simply can''t fly in — which means the margin for a poor decision is genuinely thinner. Your DPE is listening for evidence that you understand not just how to fly the approach, but when not to attempt it at all."], "tip": {"label": "Instructor Tip — Read the ACS Yourself", "body": "This guide maps every question to its ACS reference on purpose — use that reference to go read the actual Instrument Rating ACS language for that Task. A DPE is quoting from that exact document, and familiarity with its actual phrasing will make you sound like you know the standard, not just the topic."}}, {"h": "How Oral Exams Are Evaluated", "body": ["The instrument oral exam is not a test of whether you can recite facts — it''s a structured, scenario-based conversation designed to reveal how you think under exactly the kind of ambiguity a real IFR flight produces. Expect your examiner to open with a specific planned flight — a real or realistic route, aircraft, and weather picture — and reason through it with you, weaving in regulatory and technical questions naturally as the scenario unfolds.", "Within each ACS Task, your examiner is listening for three things: Knowledge (do you know the correct information), Risk Management (can you identify and mitigate the relevant risk, including recognizing when a flight shouldn''t be attempted at all), and Skill (where applicable, can you demonstrate the associated procedure, generally during the flight portion under the hood or in actual IMC)."]}]'::jsonb, 0, 'instrument'),
  ('lesson-instrument-checkride-day', 'Checkride Day Preparation', 'Section 10 · Documents, currency, and composure', '[{"h": "Overview", "body": ["Checkride day preparation for the instrument rating carries an extra layer of documentation and equipment currency beyond what a private pilot checkride requires — GPS database currency and IFR-specific inspection records among them. Review this checklist a few days out, not the morning of."]}, {"h": "Documents and Records Checklist", "list": ["Photo ID and current medical certificate (or BasicMed qualification, if applicable to the flight portion aircraft and operation)", "Complete, signed logbook showing all 61.65 experience requirements, including the specific 250nm/three-airport cross-country flight", "All required instructor endorsements for the practical test, and for the knowledge test if applicable", "Airman Knowledge Test Report (AKTR)", "Completed IACRA application (Form 8710-1), reviewed for accuracy well in advance", "Aircraft documents — Airworthiness certificate, Registration, radio station license if applicable, and Operating limitations/POH (AROW)", "Current weight and balance data matching the aircraft''s actual configuration", "Proof of current pitot-static/altimeter (91.411) and transponder (91.413) inspections within the preceding 24 calendar months", "Current charts and approach plates for the planned route and airports, or current subscription/database status if using an EFB", "Current GPS navigation database, if the aircraft''s approach-capable GPS requires one for the planned approaches"]}, {"h": "Checkride Day, Chronologically", "list": ["Document review: the examiner reviews the applicant''s certificate, medical, logbook, endorsements, and the aircraft''s documents before any technical discussion begins.", "The oral exam: a scenario-based conversation built around a specific planned IFR flight, moving through preflight planning, clearances, weather, systems, approaches, and emergency and lost-communications procedures.", "The flight portion: instrument flight under the hood or in actual IMC if conditions allow, covering basic instrument maneuvers, holding, intercepting and tracking, at least one non-precision and one precision or approach-with-vertical-guidance procedure, partial panel work, unusual attitude recovery, and a missed approach.", "The debrief: the examiner reviews performance directly, area by area, and issues either a temporary certificate or a Notice of Disapproval identifying specific areas for further training if needed."]}]'::jsonb, 1, 'instrument');
